try {
  const item = $input.first().json;
  const body = item.body || {};
  // Shared-secret check (X-Webhook-Token header must match N8N_WEBHOOK_SECRET)
  const SECRET = $env.N8N_WEBHOOK_SECRET || '';
  if (SECRET && (item.headers || {})['x-webhook-token'] !== SECRET) {
    return [{json: {result: 'Request rejected: missing or wrong X-Webhook-Token'}}];
  }
  const BUSINESS = $env.BUSINESS_NAME || 'Your Company';
  const REGION = $env.BUSINESS_REGION || 'your region';
  const BOOKING = $env.CALENDLY_URL || '';
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://ollama:11434/v1/chat/completions',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({
      model: 'qwen2.5:14b',
      max_tokens: 1500,
      messages: [
        {role: 'system', content: 'You are a B2B sales email writer for ' + BUSINESS + ', a CMMC consulting firm in ' + REGION + '. Write a concise, professional cold outreach email to a defense contractor who needs CMMC Level 2 help. Keep it under 200 words. Lead with a specific pain point related to their industry. End with a soft CTA offering a free 30-minute gap assessment with a direct booking link: ' + BOOKING + ' Sound human, not like marketing copy. Output ONLY the email (subject line + body). No word counts, no meta-commentary.'},
        {role: 'user', content: `Write a cold outreach email to ${(body.company && body.company !== "Unknown") ? body.company : "this defense contractor"} (NAICS: ${body.naics || '541512'}). Context: ${body.notes || 'No additional context.'}`}
      ]
    }),
    timeout: 60000
  });
  const data = typeof resp === 'string' ? JSON.parse(resp) : resp;
  const text = data?.choices?.[0]?.message?.content || JSON.stringify(data);
  return [{json: {result: text}}];
} catch(e) {
  return [{json: {result: 'Error: ' + e.message}}];
}
